INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('09fbf4de-26cd-4257-ad1f-04d5c75458f6', 'c3c3c3c3-3030-4000-8000-000000000003', 12, 'Dia 12 — Mente renovada', 'Semana 2: Organizar', '{"pch": "Transformai-vos pela renova\u00e7\u00e3o da mente\u2026 Pensar diferente \u00e9 o come\u00e7o de viver diferente.", "verse": "Rm 12,2", "lectio": "Leia Rm 12,1-2. Culto racional.", "practice": "Identifique 1 pensamento negativo recorrente. Substitua por uma verdade b\u00edblica.", "question": "Que padr\u00e3o de pensamento precisa mudar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;